(7370590, 1154550, 173844, '<td valign="top">Just beautiful.  The sky is magical.  The light on the herons lends great immediacy.  The "poses"  are precisely keyed to alternate wing beats and the lift of the legs.  I love that the plumage is a bit rough, unlike in a guide book, allowing the bird''s uniqueness to show.</td>', 'Just beautiful.  The sky is magical.  The light on the herons lends great immediacy.  The "poses"  are precisely keyed to alternate wing beats and the lift of the legs.  I love that the plumage is a bit rough, unlike in a guide book, allowing the bird''s uniqueness to show.', '2015-06-23 16:25:47.000000', NULL, 1),
(7370592, 1154977, 173844, '<td valign="top">Her eyes are open, but it seems a dream.  It''s a wonderful image, not least a result of the restrained blues and softly complementary beige and gray. The birds overhead secure the fantasy.  My favorite touch is the shadow of the sofa cast upon the sky, intermingling the framework of inside and outside.  Reminiscent of Henri Rousseau''s painting "The Sleeping Gypsy".</td>', 'Her eyes are open, but it seems a dream.  It''s a wonderful image, not least a result of the restrained blues and softly complementary beige and gray. The birds overhead secure the fantasy.  My favorite touch is the shadow of the sofa cast upon the sky, intermingling the framework of inside and outside.  Reminiscent of Henri Rousseau''s painting "The Sleeping Gypsy".', '2015-06-23 16:26:10.000000', NULL, 1),
(7370594, 1153458, 173844, '<td valign="top">Whimsical and beautifully handled.  A pleasing selection of unusual blues.  A lot of imagination has gone into this creation.  Yet, I''m curious as to why the Rain Maker is situated in this seeming dead end, facing away from the viewer.  I get a claustrophobic feeling.  Just a personal impression that doesn''t lessen my admiration of the overall achievement.</td>', 'Whimsical and beautifully handled.  A pleasing selection of unusual blues.  A lot of imagination has gone into this creation.  Yet, I''m curious as to why the Rain Maker is situated in this seeming dead end, facing away from the viewer.  I get a claustrophobic feeling.  Just a personal impression that doesn''t lessen my admiration of the overall achievement.', '2015-06-23 16:27:00.000000', NULL, 1),
(7370595, 1154678, 173844, '<td valign="top">Although I''m personally resistant to the appeal of modern architecture, this image is very beautiful and provides a counterweight to my prejudice.  The perspective, featuring a right angle of glass and textured wall and continuing reflection, is most winning and employed in a starkly satisfying composition.  The continuum of blues, with some overtones of pink, is also remarkable.</td>', 'Although I''m personally resistant to the appeal of modern architecture, this image is very beautiful and provides a counterweight to my prejudice.  The perspective, featuring a right angle of glass and textured wall and continuing reflection, is most winning and employed in a starkly satisfying composition.  The continuum of blues, with some overtones of pink, is also remarkable.', '2015-06-23 16:28:02.000000', NULL, 1),
(7370596, 1154649, 173844, '<td valign="top">A mysterious, imaginative, sci-fi, cinematic and very blue image.  Highly creative utilization of camera, lenses and hoods, which deepens the symbolic overtones of the narrative.  The claw-like left hand is out of proportion, unless it''s intended to be a large claw-like left hand.  The path seems to consist of hardened lava, but I can''t help thinking guano.  Nevertheless, a fine image that appears to be an out-take from a movie I''d be eager to see.</td>', 'A mysterious, imaginative, sci-fi, cinematic and very blue image.  Highly creative utilization of camera, lenses and hoods, which deepens the symbolic overtones of the narrative.  The claw-like left hand is out of proportion, unless it''s intended to be a large claw-like left hand.  The path seems to consist of hardened lava, but I can''t help thinking guano.  Nevertheless, a fine image that appears to be an out-take from a movie I''d be eager to see.', '2015-06-23 16:28:57.000000', NULL, 1),
(7370597, 1154707, 173844, '<td valign="top">Though I haven''t been able to completely match the images to the rhyme, it''s a striking take on the challenge.  Gonna leave it at that.</td>', 'Though I haven''t been able to completely match the images to the rhyme, it''s a striking take on the challenge.  Gonna leave it at that.', '2015-06-23 16:29:08.000000', NULL, 1),
(7370598, 1153882, 173844, '<td valign="top">Startling image of some creature about to have me for lunch. Despite the feeling that this is taken in a museum, it still has great power and presence.  It''s the kiddie pool for me.</td>', 'Startling image of some creature about to have me for lunch. Despite the feeling that this is taken in a museum, it still has great power and presence.  It''s the kiddie pool for me.', '2015-06-23 16:29:37.000000', NULL, 1),
(7370599, 1154710, 173844, '<td valign="top">Handsome image of either nutritious breakfast fare or Higg''s bosons throwing off a particle zoo.  In either case, a luscious tour de force.</td>', 'Handsome image of either nutritious breakfast fare or Higg''s bosons throwing off a particle zoo.  In either case, a luscious tour de force.', '2015-06-23 16:30:15.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(7370602, 1153530, 173844, '<td valign="top">Pretty, blue fantasy that dazzles, while at the same time has a bit of an assembled feel.  Well, of course an image of this type has to be assembled, but maybe what I''m getting at is that fewer components might be more convincing and less busy.  My eye, and this is obviously subjective, wants to concentrate on the figure and the castle.  I like the moonlit atmosphere and the sense that the figure actually appears to be a child in adult clothing.</td>', 'Pretty, blue fantasy that dazzles, while at the same time has a bit of an assembled feel.  Well, of course an image of this type has to be assembled, but maybe what I''m getting at is that fewer components might be more convincing and less busy.  My eye, and this is obviously subjective, wants to concentrate on the figure and the castle.  I like the moonlit atmosphere and the sense that the figure actually appears to be a child in adult clothing.', '2015-06-23 16:30:54.000000', NULL, 1),
(7370603, 1154191, 173844, '<td valign="top">Pretty after-the-storm sky buffered by a drop-bespattered window.  It''s a small study of a large expanse that works quite tidily.</td>', 'Pretty after-the-storm sky buffered by a drop-bespattered window.  It''s a small study of a large expanse that works quite tidily.', '2015-06-23 16:31:04.000000', NULL, 1),
(7370604, 1154729, 173844, '<td valign="top">Beautifully done fantasy image.  The woman is poised, balanced, on the threshold of new life.  Baby blue.  The somewhat somber blue of the spheres and the overcast sky partner well.  Perhaps far-fetched, but it''s almost as if the location is inside a womb.</td>', 'Beautifully done fantasy image.  The woman is poised, balanced, on the threshold of new life.  Baby blue.  The somewhat somber blue of the spheres and the overcast sky partner well.  Perhaps far-fetched, but it''s almost as if the location is inside a womb.', '2015-06-23 16:31:23.000000', NULL, 1),
(7371775, 1154977, 176157, '<td valign="top">This is cool.  I like it.</td>', 'This is cool.  I like it.', '2015-06-24 12:54:27.000000', NULL, 1),
(7371785, 1154678, 176157, '<td valign="top">Nice composition here.  I like that the windows are so clean.</td>', 'Nice composition here.  I like that the windows are so clean.', '2015-06-24 12:57:18.000000', NULL, 1),
(7371792, 1154946, 176157, '<td valign="top"><strike></strike></td>', '', '2015-06-24 13:00:09.000000', NULL, 1),
(7371965, 1153421, 156466, '<td valign="top">If only there wasn''t the window reflection.</td>', 'If only there wasn''t the window reflection.', '2015-06-24 16:15:13.000000', NULL, 1),
(7372598, 1154949, 156466, '<td valign="top">Always like a small world photo that avoids an obvious seam.</td>', 'Always like a small world photo that avoids an obvious seam.', '2015-06-25 12:16:20.000000', NULL, 1),
(7372600, 1153530, 156466, '<td valign="top">It''s very well executed, but the fact that the signpost is so small that I can''t read it makes this feel far more thrown together than it should.  Bigger or missing sign post and I''m thinking 8 or 9.  I didn''t give it that.</td>', 'It''s very well executed, but the fact that the signpost is so small that I can''t read it makes this feel far more thrown together than it should.  Bigger or missing sign post and I''m thinking 8 or 9.  I didn''t give it that.', '2015-06-25 12:18:05.000000', NULL, 1),
(7372610, 1154729, 156466, '<td valign="top">This is straight off a cover of some photography book that I can''t seem to think of.  Not that that''s a bad thing because it''s extremely well done.</td>', 'This is straight off a cover of some photography book that I can''t seem to think of.  Not that that''s a bad thing because it''s extremely well done.', '2015-06-25 12:20:00.000000', NULL, 1),
