(7372620, 1154976, 156466, '<td valign="top">Love the picture. not the title. Don''t worry, I don''t do mandatory sentencing.</td>', 'Love the picture. not the title. Don''t worry, I don''t do mandatory sentencing.', '2015-06-25 12:27:30.000000', NULL, 1),
(7372622, 1154831, 156466, '<td valign="top">Or not</td>', 'Or not', '2015-06-25 12:27:42.000000', NULL, 1),
(7372624, 1153382, 156466, '<td valign="top">Like the idea.  But I''m thinking I might have preferred gold/silver/lighter numbers on the clock.  Or just Roman numerals at the 12/3/6/9 spots.  And a clock-watcher should be looking at 4:58 or something close to quitting time.</td>', 'Like the idea.  But I''m thinking I might have preferred gold/silver/lighter numbers on the clock.  Or just Roman numerals at the 12/3/6/9 spots.  And a clock-watcher should be looking at 4:58 or something close to quitting time.', '2015-06-25 12:30:56.000000', NULL, 1),
(7372625, 1154648, 156466, '<td valign="top">No, it''s not</td>', 'No, it''s not', '2015-06-25 12:31:49.000000', NULL, 1),
